// enrollments/enrollment.module.ts
@Module({
  imports: [CourseModule, EnrollmentDataModule],
  providers: [EnrollmentService],          // constructor(enrollments: EnrollmentRepository, courses: CourseService)
  exports: [EnrollmentService],
})
export class EnrollmentModule {}

// enrollments/enrollment.module.spec.ts
const moduleRef = await Test.createTestingModule({ imports: [EnrollmentModule] })
  .overrideProvider(EnrollmentRepository).useValue(new InMemoryEnrollmentRepository())
  .overrideProvider(CourseRepository).useValue(new InMemoryCourseRepository(seedCourses))
  .compile();
const enrollments = moduleRef.get(EnrollmentService);

Statement: "If a later change removed CourseModule from the imports of EnrollmentModule, this test would fail at compile(), even though both repositories are fakes."

